/* eslint-disable */
/* global WebImporter */

/**
 * Parser for cards-service. Base: cards (no images).
 * Source: rendered EDS page — decorated output of blocks/cards-service/cards-service.js
 *   (ul > li > .cards-service-card-body > span.cards-service-arrow + p.cards-service-index + h3 + p).
 * Model (cards-service-item): text (richtext) only.
 * Authored rows: one per service = single cell [number p + heading + description p].
 * The arrow span is generated by the block JS and is dropped; the "01" index is
 * kept as an authored paragraph (block JS uses it as-is).
 */
export default function parse(element, { document }) {
  const cells = [];

  const items = [...element.querySelectorAll(':scope > ul > li')];
  items.forEach((li) => {
    const body = li.querySelector('.cards-service-card-body');
    const textFrag = document.createDocumentFragment();
    const nodes = body
      ? [...body.children].filter((el) => !el.classList.contains('cards-service-arrow') && el.textContent.trim())
      : [];
    if (nodes.length) {
      textFrag.appendChild(document.createComment(' field:text '));
      nodes.forEach((n) => textFrag.appendChild(n));
    }
    cells.push([textFrag]);
  });

  const block = WebImporter.Blocks.createBlock(document, { name: 'cards-service', cells });
  element.replaceWith(block);
}
